import threading

results = []
lock = threading.Lock()
errors = []

def fetch_and_store(item_id):
    try:
        data = f"result-{item_id}"
        with lock:
            results.append(data)
    except Exception as exc:
        errors.append(exc)

threads = [threading.Thread(target=fetch_and_store, args=(i,)) for i in range(10)]
for t in threads:
    t.start()
for t in threads:
    t.join()

if errors:
    raise errors[0]
print(len(results))   # reliably 10
